mapper.insert:

    SELECT fn_get_dynamic_seq('utb_usage_history') AS usage_history_seq


INSERT INTO "MP_IPMS_PA".utb_usage_history (
         usage_history_seq
       , user_mst_seq
       , office_seq
       , menu_name
       , action_name
       , req_url
       , req_method
       , client_ip
       , user_agent
       , target_class
       , target_method
       , create_user
       , create_at
       , del_yn
       , note
) VALUES (
           #{usageHistorySeq}
         , #{userMstSeq}
         , #{officeSeq}
         , #{menuName}
         , #{actionName}
         , #{reqUrl}
         , #{reqMethod}
         , NULLIF(#{clientIp}, '')::inet
         , #{userAgent}
         , #{targetClass}
         , #{targetMethod}
         , #{userMstSeq}
         , CURRENT_TIMESTAMP
         , 'N'
         , #{note}
         )
ON CONFLICT (usage_history_seq) DO NOTHING
